// The defense's chart, deterministic so practice pays off and scores are comparable. Its
// notes come from the level's music track (trackChart.ts, generated by
// backend/tools/thesis_chart.py): each one sits on an onset of the track, on its sixteenth-note
// grid, and the four phases start on the track's own break bars. Song time is track time.

import { TRACK_CHART } from "./trackChart";
import { TEXT } from "../src/misc/text";

export type Phase = "opening" | "cross" | "meltdown" | "final";

export interface Note {
    id: number;
    time: number; // ms of track time, when the note reaches the hit line
    lane: number; // 0–3, LANE_KEYS order
    gold: boolean;
}

export interface Section {
    phase: Phase;
    title: string;
    subtitle: string;
}

export interface PhaseMark {
    time: number;
    section: Section;
}

export interface Chart {
    notes: Note[];
    phases: PhaseMark[];
    end: number; // ms when the defense is over
}

// The generated data: beat grid, phase starts and notes as [time ms, lane, golden].
export interface TrackChart {
    beatMs: number;
    firstBeatMs: number; // the track's first strong downbeat
    durationMs: number;
    end: number;
    phases: { phase: Phase; time: number }[];
    notes: [number, number, boolean][];
}

// Titles and subtitles are in shared/text.json (thesisDefense.sections).
const SECTION_TEXT = TEXT.thesisDefense.sections;

export const SECTIONS: Record<Phase, Section> = {
    opening: { phase: "opening", ...SECTION_TEXT.opening },
    cross: { phase: "cross", ...SECTION_TEXT.cross },
    meltdown: { phase: "meltdown", ...SECTION_TEXT.meltdown },
    final: { phase: "final", ...SECTION_TEXT.final },
};

export function buildTrackChart(track: TrackChart): Chart {
    const notes = [...track.notes]
        .sort((a, b) => a[0] - b[0] || a[1] - b[1])
        .map(([time, lane, gold], id) => {
            if (!Number.isInteger(lane) || lane < 0 || lane > 3)
                throw new Error(`Note at ${time} ms has lane ${lane}`);
            return { id, time, lane, gold };
        });
    return {
        notes,
        phases: track.phases.map(({ phase, time }) => ({
            time,
            section: SECTIONS[phase],
        })),
        end: track.end,
    };
}

export const BEAT_MS = TRACK_CHART.beatMs;
export const BAR_MS = 4 * BEAT_MS;
// Beat lines and the hit rule's pulse follow the track's grid, starting from its first beat.
export const BEAT_ORIGIN_MS = TRACK_CHART.firstBeatMs;
export const DEFENSE_CHART = buildTrackChart(TRACK_CHART);
